		return
	}
	a := make([]int64, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &a[i])
	}

	// Split into two halves
	n1 := n / 2
	n2 := n - n1

	left := make([]int64, 1<<n1)
	for mask := 0; mask < (1 << n1); mask++ {
		var sum int64
		for i := 0; i < n1; i++ {
			if mask&(1<<i) != 0 {
				sum += a[i]
			}
		}
		left[mask] = sum % m
	}

	right := make([]int64, 1<<n2)
	for mask := 0; mask < (1 << n2); mask++ {
		var sum int64
		for i := 0; i < n2; i++ {
			if mask&(1<<i) != 0 {
				sum += a[n1+i]
			}
		}
		right[mask] = sum % m
	}

	// Sort right
	quickSort(right, 0, len(right)-1)

	var ans int64
	for _, lv := range left {
		// we want lv + rv < m, so rv < m - lv
		target := m - lv
		idx := upperBound(right, target-1)
		if idx > 0 {
			val := (lv + right[idx-1]) % m
			if val > ans {
				ans = val
			}
		}
		if lv > ans {
			ans = lv
		}
	}

	fmt.Println(ans)
}

func quickSort(a []int64, l, r int) {
	if l >= r {
		return
	}
	i, j := l, r
	pivot := a[(l+r)>>1]
	for i <= j {
		for a[i] < pivot {
			i++
		}
		for a[j] > pivot {
			j--
		}
		if i <= j {
			a[i], a[j] = a[j], a[i]
			i++
			j--
		}
	}
	if l < j {
		quickSort(a, l, j)
	}
	if i < r {
		quickSort(a, i, r)
	}
}

func upperBound(a []int64, x int64) int {
	l, r := 0, len(a)
	for l < r {
		m := (l + r) >> 1
		if a[m] <= x {
			l = m + 1
		} else {
			r = m
		}
	}
	return l
}

